int hidp_ioctl(struct socket *sock, unsigned int cmd, void __user *argp)
{
    int err = 0;
    struct sock *sk = sock->sk;
    struct hidp_connadd add;
    struct hidp_conndel del;
    struct hidp_connlist connlist;
    struct hidp_conninfo conninfo;

    if (!capable(CAP_NET_ADMIN))
        return -EPERM;

    switch (cmd) {
    case HIDPADDCONN:
        if (copy_from_user(&add, argp, sizeof(add)))
            return -EFAULT;
        hidp_add_connection(add.bdaddr, add.handle, add.type);
        break;

    case HIDPDELCONN:
        if (copy_from_user(&del, argp, sizeof(del)))
            return -EFAULT;
        hidp_del_connection(del.handle);
        break;

    case HIDPGETCONNLIST:
        if (copy_from_user(&connlist, argp, sizeof(connlist)))
            return -EFAULT;
        err = hidp_get_connlist(&connlist);
        if (err < 0)
            return err;
        if (copy_to_user(argp, &connlist, sizeof(connlist)))
            return -EFAULT;
        break;

    case HIDPGETCONNINFO:
        if (copy_from_user(&conninfo, argp, sizeof(conninfo)))
            return -EFAULT;
        err = hidp_get_conninfo(conninfo.handle, &conninfo);
        if (err < 0)
            return err;
        if (copy_to_user(argp, &conninfo, sizeof(conninfo)))
            return -EFAULT;
        break;

    default:
        return -EINVAL;
    }

    return 0;
}

int hidp_ioctl(struct socket *sock, unsigned int cmd, void __user *argp)
{
    int ret = -EINVAL;
    struct hidp_connadd add;
    struct hidp_conndel del;
    struct hidp_connlist connlist;
    struct hidp_conninfo conninfo;

    if (!capable(CAP_NET_ADMIN))
        return -EPERM;

    switch (cmd) {
    case HIDP_ADD_CONN:
        if (copy_from_user(&add, argp, sizeof(add)))
            return -EFAULT;
        ret = hidp_add_connection(&add);
        break;
    case HIDP_DEL_CONN:
        if (copy_from_user(&del, argp, sizeof(del)))
            return -EFAULT;
        ret = hidp_del_connection(&del);
        break;
    case HIDP_GET_CONNLIST:
        if (copy_from_user(&connlist, argp, sizeof(connlist)))
            return -EFAULT;
        ret = hidp_get_connlist(&connlist);
        if (ret >= 0)
            if (copy_to_user(argp, &connlist, sizeof(connlist)))
                ret = -EFAULT;
        break;
    case HIDP_GET_CONNINFO:
        if (copy_from_user(&conninfo, argp, sizeof(conninfo)))
            return -EFAULT;
        ret = hidp_get_conninfo(&conninfo);
        if (ret >= 0)
            if (copy_to_user(argp, &conninfo, sizeof(conninfo)))
                ret = -EFAULT;
        break;
    default:
        ret = -EINVAL;
        break;
    }

    return ret;
}
